					       .quote(order)
					       .flatMap(body -> persist
																														? service
						                          .firebase(order.sku())
						                          .map(saved -> Response
						                                        .ok(body)
						                                        .build())
																														: Uni
						                          .createFrom()
						                          .item(Response
						                                .ok(body)
						                                .build()))
												.onFailure()
					       .invoke(Throwable::printStackTrace)
					       .onFailure()
					       .recoverWithItem(f -> error(502, "UPSTREAM_FAILURE"));
		}

		@GET
		@Path("retry/{id}")
